-- Run in Supabase SQL Editor. Dedicated tables; no direct public table access.
create table if not exists public.gv_rooms (id text primary key, token text not null, state jsonb default '{}', backup jsonb);
create table if not exists public.gv_inbox (id uuid primary key default gen_random_uuid(), room text references public.gv_rooms(id), guest text, name text, kind text, value text, created_at timestamptz default now());
create table if not exists public.gv_roles (room text references public.gv_rooms(id), guest text, value text, primary key(room,guest));
alter table public.gv_rooms enable row level security;
alter table public.gv_inbox enable row level security;
alter table public.gv_roles enable row level security;
revoke all on public.gv_rooms,public.gv_inbox,public.gv_roles from anon,authenticated;
create or replace function public.gv_create(r text,t text) returns boolean language plpgsql security definer set search_path='' as $$begin if length(t)<32 or length(r)<16 then raise exception 'Use generated room and token'; end if; insert into public.gv_rooms(id,token) values(r,t) on conflict do nothing; if not exists(select 1 from public.gv_rooms where id=r and token=t) then raise exception 'Invalid host token'; end if; return true; end$$;
create or replace function public.gv_publish(r text,t text,p jsonb,b jsonb) returns boolean language plpgsql security definer set search_path='' as $$begin update public.gv_rooms set state=p,backup=b where id=r and token=t; if not found then raise exception 'Invalid host token'; end if; return true; end$$;
create or replace function public.gv_restore(r text,t text) returns jsonb language sql security definer set search_path='' as $$select backup from public.gv_rooms where id=r and token=t$$;
create or replace function public.gv_public(r text) returns jsonb language sql security definer set search_path='' as $$select state from public.gv_rooms where id=r$$;
create or replace function public.gv_submit(r text,g text,n text,k text,v text) returns boolean language plpgsql security definer set search_path='' as $$begin if length(g)<32 or length(n) not between 1 and 80 or length(v)>500 or k not in ('join','buzz','answer','vote') then raise exception 'Invalid submission'; end if; if exists(select 1 from public.gv_inbox where room=r and guest=g and created_at>now()-interval '1 second') then raise exception 'Wait one second'; end if; insert into public.gv_inbox(room,guest,name,kind,value) values(r,g,n,k,v); return true; end$$;
create or replace function public.gv_events(r text,t text) returns jsonb language sql security definer set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at),'[]'::jsonb) from (select i.* from public.gv_inbox i join public.gv_rooms h on h.id=i.room where h.id=r and h.token=t order by i.created_at desc limit 200)e$$;
create or replace function public.gv_role(r text,t text,g text,v text) returns boolean language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.gv_rooms where id=r and token=t) then raise exception 'Invalid host token'; end if; insert into public.gv_roles(room,guest,value) values(r,g,left(v,500)) on conflict(room,guest) do update set value=excluded.value; return true; end$$;
create or replace function public.gv_getrole(r text,g text) returns text language sql security definer set search_path='' as $$select value from public.gv_roles where room=r and guest=g$$;